// Thin typed wrappers around `invoke()`. Once `bindings.ts` is generated by `tauri-specta`
// (during the first `cargo tauri dev` / `cargo build`), these signatures align with the Rust
// commands. Until then this file uses minimal hand-written shapes so the frontend type-checks.

import { invoke } from "@tauri-apps/api/core";
import type {
  Asset,
  CreateObjectInput,
  Folder,
  GcodeMetadata,
  ObjectFull,
  ObjectSummary,
  Object as Obj,
  ParsedGcode,
  SearchHit,
  Tag,
  UpdateObjectPatch,
  MountedDrive,
  UsbTarget,
  SyncReport,
  UrlImportReport,
  FolderImportReport,
  NewProjectOutcome,
  OrcaPresets,
  OrcaDefaults,
} from "./types";

export const api = {
  // folders
  listFolders: () => invoke<Folder[]>("list_folders"),
  createFolder: (parent_id: number | null, name: string) =>
    invoke<Folder>("create_folder", { parentId: parent_id, name }),
  renameFolder: (id: number, name: string) => invoke<Folder>("rename_folder", { id, name }),
  moveFolder: (id: number, new_parent: number | null) =>
    invoke<void>("move_folder", { id, newParent: new_parent }),
  deleteFolder: (id: number) => invoke<void>("delete_folder", { id }),

  // objects
  listObjects: (folder_id: number | null) =>
    invoke<ObjectSummary[]>("list_objects", { folderId: folder_id }),
  listAllObjects: () => invoke<ObjectSummary[]>("list_all_objects"),
  getObject: (id: number) => invoke<ObjectFull>("get_object", { id }),
  createObject: (input: CreateObjectInput) => invoke<Obj>("create_object", { input }),
  updateObject: (id: number, patch: UpdateObjectPatch) =>
    invoke<Obj>("update_object", { id, patch }),
  deleteObject: (id: number) => invoke<void>("delete_object", { id }),
  moveObject: (id: number, folder_id: number | null) =>
    invoke<void>("move_object", { id, folderId: folder_id }),
  setMainProject: (object_id: number, asset_id: number) =>
    invoke<void>("set_main_project", { objectId: object_id, assetId: asset_id }),

  // files
  addStl: (object_id: number, source_path: string) =>
    invoke<Asset>("add_stl", { objectId: object_id, sourcePath: source_path }),
  addScad: (object_id: number, source_path: string) =>
    invoke<Asset>("add_scad", { objectId: object_id, sourcePath: source_path }),
  addCadquery: (object_id: number, source_path: string) =>
    invoke<Asset>("add_cadquery", { objectId: object_id, sourcePath: source_path }),
  addDoc: (object_id: number, source_path: string) =>
    invoke<Asset>("add_doc", { objectId: object_id, sourcePath: source_path }),
  writeDoc: (asset_id: number, content: string) =>
    invoke<void>("write_doc", { assetId: asset_id, content }),
  addGcode: (object_id: number, source_path: string) =>
    invoke<[Asset, GcodeMetadata]>("add_gcode", { objectId: object_id, sourcePath: source_path }),
  removeAsset: (id: number) => invoke<void>("remove_asset", { id }),
  setCoverImage: (object_id: number, source_path: string) =>
    invoke<Asset>("set_cover_image", { objectId: object_id, sourcePath: source_path }),
  addAttachment: (object_id: number, source_path: string) =>
    invoke<Asset>("add_attachment", { objectId: object_id, sourcePath: source_path }),
  setCoverFromAsset: (object_id: number, asset_id: number) =>
    invoke<void>("set_cover_from_asset", { objectId: object_id, assetId: asset_id }),
  setCoverFromRender: (object_id: number, png: number[], filename: string) =>
    invoke<Asset>("set_cover_from_render", { objectId: object_id, png, filename }),
  readAssetBytes: (id: number) => invoke<number[]>("read_asset_bytes", { id }),
  parseGcodeFile: (path: string) => invoke<ParsedGcode>("parse_gcode_file", { path }),

  // tags
  listTags: () => invoke<Tag[]>("list_tags"),
  createTag: (name: string, color: string | null) => invoke<Tag>("create_tag", { name, color }),
  attachTag: (entity_kind: string, entity_id: number, tag_id: number) =>
    invoke<void>("attach_tag", { entityKind: entity_kind, entityId: entity_id, tagId: tag_id }),
  detachTag: (entity_kind: string, entity_id: number, tag_id: number) =>
    invoke<void>("detach_tag", { entityKind: entity_kind, entityId: entity_id, tagId: tag_id }),

  // search
  search: (query: string, kinds: string[] | null) => invoke<SearchHit[]>("search", { query, kinds }),

  // tools (OrcaSlicer)
  getOrcaPath: () => invoke<string | null>("get_orca_path"),
  setOrcaPath: (path: string | null) => invoke<void>("set_orca_path", { path }),
  openAssetInOrca: (asset_id: number) =>
    invoke<void>("open_asset_in_orca", { assetId: asset_id }),
  newOrcaProject: (object_id: number) =>
    invoke<NewProjectOutcome>("new_orca_project", { objectId: object_id }),
  listOrcaPresets: () => invoke<OrcaPresets>("list_orca_presets"),
  getOrcaDefaults: () => invoke<OrcaDefaults>("get_orca_defaults"),
  setOrcaDefaults: (machine_path: string | null, filament_path: string | null) =>
    invoke<void>("set_orca_defaults", { machinePath: machine_path, filamentPath: filament_path }),

  // tools (OpenSCAD)
  getOpenscadPath: () => invoke<string | null>("get_openscad_path"),
  setOpenscadPath: (path: string | null) => invoke<void>("set_openscad_path", { path }),
  openAssetInOpenscad: (asset_id: number) =>
    invoke<void>("open_asset_in_openscad", { assetId: asset_id }),
  renderScadPreview: (asset_id: number) =>
    invoke<number[]>("render_scad_preview", { assetId: asset_id }),

  // settings
  getStlPreviewMaxBytes: () => invoke<number>("get_stl_preview_max_bytes"),
  setStlPreviewMaxBytes: (bytes: number) =>
    invoke<void>("set_stl_preview_max_bytes", { bytes }),
  getCleanKobraGcode: () => invoke<boolean>("get_clean_kobra_gcode"),
  setCleanKobraGcode: (enabled: boolean) =>
    invoke<void>("set_clean_kobra_gcode", { enabled }),
  getUsbAutoSync: () => invoke<boolean>("get_usb_auto_sync"),
  setUsbAutoSync: (enabled: boolean) => invoke<void>("set_usb_auto_sync", { enabled }),

  // system
  revealObjectInExplorer: (object_id: number) =>
    invoke<void>("reveal_object_in_explorer", { objectId: object_id }),
  classifyPaths: (paths: string[]) =>
    invoke<("dir" | "file" | "missing")[]>("classify_paths", { paths }),
  // Sweep the library for on-disk files not yet tracked (e.g. gcode a slicer just
  // saved into an object's folder). Returns how many files were newly discovered.
  rescanLibrary: () => invoke<number>("rescan_library"),

  // usb sync
  listMountedDrives: () => invoke<MountedDrive[]>("list_mounted_drives"),
  registerUsbTarget: (mount_path: string, label: string, force?: boolean) =>
    invoke<UsbTarget>("register_usb_target", {
      mountPath: mount_path,
      label,
      force: force ?? null,
    }),
  clearUsbTarget: () => invoke<void>("clear_usb_target"),
  getUsbTarget: () => invoke<UsbTarget | null>("get_usb_target"),
  syncUsbNow: (deep?: boolean) => invoke<SyncReport>("sync_usb_now", { deep: deep ?? null }),
  setGcodeExport: (asset_id: number, export_to_usb: boolean) =>
    invoke<void>("set_gcode_export", { assetId: asset_id, exportToUsb: export_to_usb }),

  // imports
  importFromUrl: (url: string, folder_id: number | null) =>
    invoke<UrlImportReport>("import_from_url", { url, folderId: folder_id }),
  getThingiverseToken: () => invoke<string | null>("get_thingiverse_token"),
  setThingiverseToken: (token: string | null) =>
    invoke<void>("set_thingiverse_token", { token }),
  importFolderAsObject: (source_path: string, folder_id: number | null) =>
    invoke<FolderImportReport>("import_folder_as_object", {
      sourcePath: source_path,
      folderId: folder_id,
    }),
  importFolderIntoObject: (object_id: number, source_path: string) =>
    invoke<FolderImportReport>("import_folder_into_object", {
      objectId: object_id,
      sourcePath: source_path,
    }),
};
